\begin{itemchoice}
			\itemch Ta có $C'(x) = 3x^2 - 6x - 20$.
			\itemch Số tiền bán được khi bán $x$ mét vải lụa với giá $220$ nghìn đồng/mét là $B(x)=220x$ (nghìn đồng).
			\itemch Lợi nhuận thu được khi bán $x$ mét vải lụa là
			\begin{eqnarray*}
				L(x) &=& B(x) - C(x) \\
				&=& 220x - \left(x^3 - 3x^2 - 20x + 500\right) \\
				&=& -x^3 + 3x^2 + 240x - 500 \text{ (nghìn đồng).}
			\end{eqnarray*}
			\itemch Xét hàm số $L(x) = -x^3 + 3x^2 + 240x - 500$ trên đoạn $[1; 18]$. \\
			Ta có $L'(x) = -3x^2 + 6x + 240$. \\
			$L'(x) = 0 \Leftrightarrow -3x^2 + 6x + 240 = 0 \Leftrightarrow \left[ \begin{array}{l}
x = 10 \in [1; 18] \\ x = -8 \notin [1; 18].
\end{array} \right.$ \\
			Bảng biến thiên
			\begin{center}
				<img src='HinhAnh/sol_f689d3fa54_lg_tikz_1.png' style='max-width: 100%; height: auto; display: block; margin: 10px auto;' />
			\end{center}
			Dựa vào bảng biến thiên, lợi nhuận tối đa đạt được tại $x=10$, giá trị lớn nhất là \break $L(10) = 1\,200$ (nghìn đồng).
	\end{itemchoice}

\begin{itemchoice}
			\itemch Dựa vào bảng biến thiên, hàm số đồng biến trên các khoảng $(0;1)$ và $(3;+\infty)$.
			\itemch Dựa vào bảng biến thiên, hàm số nghịch biến trên khoảng $(-\infty;0)$ và $(1;3)$.\\\itemch Xét hàm số $g(x) = f(x+1)$. Ta có $g'(x) = f'(x+1)$. \\
			Hàm số đồng biến khi và chỉ khi $$g'(x) > 0 \Leftrightarrow f'(x+1) > 0 \left[ \begin{array}{l}
0 < x+1 < 1 \\ x+1 > 3
\end{array} \right. \Leftrightarrow \left[ \begin{array}{l}
-1 < x < 0 \\  x > 2.
\end{array} \right. $$
			Do đó hàm số đồng biến trên $(2;4)$.
			\itemch Phương trình $f(x)-3=0 \Leftrightarrow f(x)=3$. \\
			Dựa vào bảng biến thiên, đường thẳng $y=3$ cắt đồ thị hàm số tại $4$ điểm phân biệt.
	\end{itemchoice}

\begin{itemchoice}
			\itemch Điểm $I(1 ;-1)$ là giao điểm của hai đường tiệm cận nên điểm $I(1 ;-1)$ là tâm đối xứng của đồ thị hàm số.\\\itemch  Nhìn vào đồ thị ta thấy đồ thị hàm số $y=f(x)$ không có đường tiệm cận ngang.\\\itemch Nhìn vào đồ thị ta thấy đồ thị hàm số $y=f(x)$ có tiệm cận đứng là đường thẳng có phương trình $x=1$.\\\itemch Tiệm cận xiên của đồ thị hàm số đi qua các điểm $(0 ; 0)$, $(1 ;-1)$ nên đường tiệm cận xiên có phương trình là $y=-x$.
	\end{itemchoice}
